    "section": "百度热搜",
    "titleZh": "女子凌晨倒24瓶爱心水只为拿走空瓶",
    "summaryZh": "2026-08-20 百度热搜第 14 名，热度 666.4万。8月17日，山西大同特产店主张女士调取监控才发现，一名女子每天凌晨3点左右都会出现在店门口，倒掉箱子里剩下的所有矿泉水，只为拿走空瓶，最多的一次倒了24瓶。19日，张女士表示“阿姨拿水没问题，我不舒服的是她把水全倒了，我发这个视频只为呼吁人们别浪费，不要把善意辜负了。”",
